nginx_locations:
# ThreatCrush: distributed x402 paywall-scrape mitigation (zones in
# conf.d/paywall-limits.conf). Exact-match so ?query variants are covered.
location = /api/v1/search {
    if ($paywall_deny_ua) { return 403; }
    limit_req zone=paywall_ip  burst=5   nodelay;
    limit_req zone=paywall_all burst=100 nodelay;
    proxy_pass http://127.0.0.1:__APP_PORT__;
    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade;
    proxy_read_timeout 300s;
    proxy_buffering off;
    proxy_buffer_size 64k;
    proxy_buffers 8 64k;
    proxy_busy_buffers_size 128k;
}
